function fromTopMm(topMm) {
  return (PAGE_H_MM - topMm) * MM;
}

// Herkent of een productregel een "Tegeltje met tekst"-standaardproduct is
// waar we een ontwerp voor kennen. Geeft het ontwerp terug (of null).
function matchTegelTekstOntwerp(li) {
  const titel = li.title || '';
  // Poort-check: moet in elk geval een "Tegeltje met ..."-product zijn,
  // voordat de individuele ontwerp-regexen (hieronder) gecontroleerd worden.
  // Oorspronkelijk alleen "tegeltje met tekst" — uitgebreid met "tegeltje
  // met hartje" toen bleek dat die productnaam-variant (bv. "Tegeltje met
  // hartje – minimalistisch liefdevol ontwerp.") hierdoor NOOIT herkend kon
  // worden, ook al matchte het ontwerp se eigen `herken`-regex prima in
  // isolatie — deze poort-check zelf blokkeerde het al eerder.
  if (!/tegeltje met (tekst|hartje)/i.test(titel)) return null;
  return TEGEL_TEKST_ONTWERPEN.find(o => o.herken.test(titel)) || null;
}

function isTegelTekstLineItem(li) {
  return matchTegelTekstOntwerp(li) !== null;
}

// Haalt de gekozen tegelkleur uit de Shopify-variant (bv. "Beige / Houten-
// houder" -> "Beige") — dezelfde plek (variant_title) als bij de andere
// tegel-/frame-producten in dit project.
function extractTegelKleur(li) {
  const variantTitle = li.variant_title || '';
  const eersteDeel = variantTitle.split('/')[0].trim();
  return eersteDeel || null;
}

function extractTegelTekstData(li) {
  const ontwerp = matchTegelTekstOntwerp(li);
  const kleur = extractTegelKleur(li);
  return { ontwerp, kleur };
}

// Zoekt in een volledige (raw) Shopify-order naar "Tegeltje met tekst"-
// productregels met een bekend ontwerp, en geeft voor elk besteld exemplaar
// (quantity) een los item terug.
function extractTegelTekstItemsFromOrder(rawOrder) {
  const items = [];
  (rawOrder.line_items || []).forEach(li => {
    const ontwerp = matchTegelTekstOntwerp(li);
    if (!ontwerp) return;
    const kleur = extractTegelKleur(li);
    const qty = li.quantity && li.quantity > 0 ? li.quantity : 1;
    for (let i = 0; i < qty; i++) {
      items.push({ title: li.title, kleur, data: { ontwerp, kleur } });
    }
  });
  return items;
}

// Laadt alle lettertype-stijlen die een ontwerp nodig heeft, met per stijl
// een terugval op een ingebouwd PDF-lettertype als het echte bestand
// ontbreekt in server/fonts/.
async function laadLettertypen(doc, ontwerp, forceerTerugval) {
  const fonts = {};
  for (const stijl of Object.keys(ontwerp.lettertypeBestanden || {})) {
    const bestandsnaam = ontwerp.lettertypeBestanden[stijl];
    const bestandsPad = path.join(__dirname, 'fonts', bestandsnaam);
    if (!forceerTerugval && fs.existsSync(bestandsPad)) {
      fonts[stijl] = await doc.embedFont(fs.readFileSync(bestandsPad));
    } else {
      if (!forceerTerugval) {
        console.warn(`[texttile] ${bestandsnaam} niet gevonden in server/fonts/ — val terug op een ingebouwd PDF-lettertype. Zie README voor hoe je het echte lettertypebestand toevoegt.`);
      }
      fonts[stijl] = await doc.embedFont(ontwerp.lettertypeTerugval[stijl] || StandardFonts.Helvetica);
    }
  }
  return fonts;
}

// Tekent het hart-icoon van een ontwerp — ondersteunt 2 opslag-eenheden
// (zie de toelichting bij TEGEL_TEKST_ONTWERPEN hierboven).
function drawHart(page, hart) {
  if (hart.eenheid === 'pdf-punten') {
    page.drawSvgPath(hart.pad, {
      x: hart.ankerXMm * MM,
      y: fromTopMm(hart.ankerTopMm),
      scale: 1, // staat al in PDF-punten, geen mm-omrekening nodig
      color: hart.kleur
    });
  } else {
    // 'genormaliseerd': eigen eenheden met een gedocumenteerde breedteMm,
    // herschaald met de experimenteel bepaalde factor.
    const hartBreedteMm = hart.breedteMm * hart.schaal;
    const hartXMm = (PAGE_W_MM - hartBreedteMm) / 2;
    page.drawSvgPath(hart.pad, {
      x: hartXMm * MM,
      y: fromTopMm(hart.topMm),
      scale: hart.schaal,
      color: hart.kleur
    });
  }
}

// Publieke functie: probeert eerst normaal te genereren (met de eigen
// lettertypebestanden van het ontwerp, indien aanwezig); mislukt dat —
// ontdekt bij "Tot de maan en achter het behang.", waar een subtiele
// structurele afwijking in het aangeleverde lettertypebestand pas bij het
// daadwerkelijk OPSLAAN van de PDF (de font-subsetting-stap) een fout gaf,
// niet eerder bij het inbedden/tekenen zelf — dan wordt de HELE generatie
// eenmalig opnieuw geprobeerd met de ingebouwde terugval-lettertypen, i.p.v.
// de bulk-export/losse download gewoon te laten mislukken. Dit dekt niet
// alleen deze ene, inmiddels zelf al gerepareerde font-bug af, maar is ook
// een algemeen vangnet voor een toekomstig, opnieuw aangeleverd lettertype
// met eenzelfde soort verborgen structuurfout.
async function generateTegelTekstPdf(data) {
  try {
    return await genereerTegelTekstPdfIntern(data, false);
  } catch (e) {
    const heeftEigenLettertype = data.ontwerp && data.ontwerp.lettertypeBestanden &&
      Object.keys(data.ontwerp.lettertypeBestanden).length > 0;
    if (!heeftEigenLettertype) throw e; // geen lettertype-gerelateerd vangnet mogelijk, gewoon de oorspronkelijke fout tonen
    console.warn(`[texttile] Genereren met het eigen lettertype mislukte (${e.message}) — probeer opnieuw met het terugval-lettertype.`);
    return await genereerTegelTekstPdfIntern(data, true);
  }
}

async function genereerTegelTekstPdfIntern(data, forceerTerugvalLettertype) {
  const doc = await PDFDocument.create();
  doc.registerFontkit(fontkit);
  const page = doc.addPage([PAGE_W_MM * MM, PAGE_H_MM * MM]);

  const ontwerp = data.ontwerp;
  if (!ontwerp) {
    throw new Error('Geen bekend tekst-ontwerp meegegeven aan generateTegelTekstPdf.');
  }

  const fonts = await laadLettertypen(doc, ontwerp, forceerTerugvalLettertype);

  // --- Hoofdtekst-kleur: zwart bij Wit/Beige, wit bij alle andere tegel-
  // kleuren (bevestigd met de opdrachtgever). Regels met accent:true zijn
  // hier bewust NIET van afhankelijk — die houden altijd hun eigen vaste
  // accentkleur (per regel meegegeven). ---
  const kleurNaam = (data.kleur || '').toLowerCase();
  const hoofdtekstKleur = LICHTE_TEGELKLEUREN.some(k => kleurNaam.includes(k)) ? COLOR_BLACK : COLOR_WHITE;

  // --- Vooraf: voor regels die een gedeelde groep vormen (regel.groep), 1x
  // een GEZAMENLIJKE, gelijke lettergrootte berekenen — i.p.v. elke regel
  // onafhankelijk zijn eigen grootte te laten kiezen. Dat laatste gaf anders
  // zichtbaar ongelijke lettergroottes binnen 1 genummerde lijst, als de ene
  // regel (bv. een langere) wél moest verkleinen om te passen en een andere
  // (kortere) regel niet. De hele groep krijgt nu de KLEINSTE grootte die
  // ELK van zijn regels nodig heeft. ---
  const groepGroottes = {};
  (ontwerp.regels || []).forEach(regel => {
    if (regel.groep === undefined || regel.maxBreedteMm === undefined) return;
    const font = fonts[regel.fontStijl];
    let sizePt = regel.puntgrootteMm * MM;
    const maxWidthPt = regel.maxBreedteMm * MM;
    while (sizePt > 2 * MM && widthOfTextLigatuurVeiligAtSize(font, regel.tekst, sizePt) > maxWidthPt) {
      sizePt -= 0.05 * MM;
    }
    if (groepGroottes[regel.groep] === undefined || sizePt < groepGroottes[regel.groep]) {
      groepGroottes[regel.groep] = sizePt;
    }
  });

  (ontwerp.regels || []).forEach(regel => {
    const font = fonts[regel.fontStijl];
    const kleur = regel.accent ? (regel.accentKleur || (ontwerp.hart && ontwerp.hart.kleur)) : hoofdtekstKleur;
    let sizePt = (regel.groep !== undefined && groepGroottes[regel.groep] !== undefined)
      ? groepGroottes[regel.groep]
      : regel.puntgrootteMm * MM;

    // Vangnet tegen tekstoverloop voor regels ZONDER groep (regels mét een
    // groep gebruiken hierboven al de gezamenlijk-berekende grootte).
    if (regel.groep === undefined && regel.maxBreedteMm !== undefined) {
      const maxWidthPt = regel.maxBreedteMm * MM;
      while (sizePt > 2 * MM && widthOfTextLigatuurVeiligAtSize(font, regel.tekst, sizePt) > maxWidthPt) {
        sizePt -= 0.05 * MM;
      }
    }

    // Standaard gecentreerd (zoals alle eerdere ontwerpen) — tenzij de regel
    // een eigen xMm meegeeft, dan links uitgelijnd vanaf die positie (nodig
    // voor ontwerpen zoals "Beste vriendin", die links uitgelijnd zijn).
    let xPt;
    if (regel.xMm !== undefined) {
      xPt = regel.xMm * MM;
    } else {
      const textWidthPt = widthOfTextLigatuurVeiligAtSize(font, regel.tekst, sizePt);
      xPt = (PAGE_W_MM * MM - textWidthPt) / 2;
    }
    drawTextLigatuurVeilig(
      page, font, regel.tekst,
      xPt, fromTopMm(regel.topMm) - sizePt * 0.75, // tekst-baseline t.o.v. de top van de tekstregel (empirisch bepaald, zie opmeet-sessie)
      sizePt, kleur
    );
  });

  // --- Lijn (optioneel, bv. bij "Beste vriendin" onder de titel) — volgt
  // ALTIJD de hoofdtekst-kleur (geen aparte accentkleur-optie nodig, is in
  // het referentiebestand ook gewoon dezelfde kleur als de tekst). ---
  if (ontwerp.lijn) {
    const lijn = ontwerp.lijn;
    page.drawRectangle({
      x: lijn.xMm * MM,
      y: fromTopMm(lijn.topMm + lijn.hoogteMm),
      width: lijn.breedteMm * MM,
      height: lijn.hoogteMm * MM,
      color: hoofdtekstKleur
    });
  }

  // --- Hartje (optioneel — sommige ontwerpen, zoals "Beste vriendin",
  // hebben er geen). Meestal een eigen, vaste kleur (ongeacht tegelkleur) —
  // tenzij het ontwerp zelf aangeeft dat het hartje de hoofdtekst-kleur moet
  // volgen (volgtHoofdtekstkleur: true), bv. om te voorkomen dat een zwart
  // hartje onzichtbaar wordt op een zwarte tegel. ---
  if (ontwerp.hart) {
    const hartKleur = ontwerp.hart.volgtHoofdtekstkleur ? hoofdtekstKleur : ontwerp.hart.kleur;
    drawHart(page, { ...ontwerp.hart, kleur: hartKleur });
  }

  // --- Verloopvormen (optioneel): 1 of meer vormen met een ECHT PDF-
  // kleurverloop i.p.v. een vlakke kleur (bv. de sterren bij "Tussen de
  // sterren") — altijd een vaste kleur/verloop, ongeacht tegelkleur (zie
  // drawGradientShapes in pdf-shared.js voor de volledige technische
  // toelichting). ---
  if (ontwerp.verloopvormen) {
    drawGradientShapes(doc, page, ontwerp.verloopvormen.vormen, ontwerp.verloopvormen.gradient);
  }

  // --- Decoratie (optioneel): 1 of meer losse vectorvormen (bv. het
  // sierlijntje-met-hartje bij "You are a limited Edition") — elk met een
  // eigen ankerpunt, rechtstreeks uit het referentiebestand gehaald. Volgt
  // ALTIJD de hoofdtekst-kleur, tenzij een vorm een eigen kleur meekrijgt. ---
  (ontwerp.decoratie || []).forEach(vorm => {
    page.drawSvgPath(vorm.pad, {
      x: vorm.xMm * MM,
      y: fromTopMm(vorm.topMm),
      color: vorm.kleur || hoofdtekstKleur
    });
  });

  return doc.save();
}

module.exports = {
  generateTegelTekstPdf, isTegelTekstLineItem, matchTegelTekstOntwerp,
  extractTegelKleur, extractTegelTekstData, extractTegelTekstItemsFromOrder,
  TEGEL_TEKST_ONTWERPEN, LICHTE_TEGELKLEUREN
};
